#include <stdio.h>

int rotLeft(int arr[],int n,int d){
    d %= n;
    for(int i = 0; i < n; i++){
        printf("%d%c", arr[(i + d) % n], i == n - 1 ? '\n' : ' ');
    }
    return 0;
}

int rotRight(int arr[],int n,int d){
    d %= n;
    for(int i = 0; i < n; i++){
        printf("%d%c", arr[(i - d + n) % n], i == n - 1 ? '\n' : ' ');
    }
    return 0;
}

