struct n *split_list(int parity){
    struct n *h = NULL, *last = NULL, *p = head;
    do {
        if(p->data % 2 == parity){
            struct n *t = (struct n*)malloc(sizeof(struct n));
            t->data = p->data;
            if(!h) h = t;
            else last->next = t;
            t->next = h;
            last = t;
        }
        p = p->next;
    } while(p != head);
    return h;
}

