#include <stdio.h>

struct node {
    int data;
    struct node *next;
};

struct node pool[1005];
int p_idx;

void swapNodes(struct node **head_ref, int x, int y) 
{ 
    if (x == y) return; 

    struct node *prevX = 0, *currX = *head_ref; 
    while (currX && currX->data != x) 
    { 
        prevX = currX; 
        currX = currX->next; 
    } 

    struct node *prevY = 0, *currY = *head_ref; 
    while (currY && currY->data != y) 
    { 
        prevY = currY; 
        currY = currY->next; 
    } 

    if (!currX || !currY) return; 

    if (prevX) prevX->next = currY; 
    else *head_ref = currY; 

    if (prevY) prevY->next = currX; 
    else *head_ref = currX; 

    struct node *temp = currY->next; 
    currY->next = currX->next; 
    currX->next = temp; 
} 

void printList(struct node *n, char *msg) 
{ 
    printf("%s", msg); 
    for (; n; n = n->next) printf("-->%d", n->data); 
    printf("\n"); 
} 

int main() 
{ 
    int n, val, x, y; 
    struct node *head = 0; 
    scanf("%d", &n); 
    for (int i = 0; i < n; i++) 
    { 
        scanf("%d", &val); 
        struct node *t = &pool[p_idx++];
        t->data = val;
        t->next = head;
        head = t; 
    } 
    scanf("%d%d", &x, &y); 
    printList(head, "before Swapping:"); 
    swapNodes(&head, x, y); 
    printList(head, "after Swapping:"); 
    return 0; 
}

