}

struct Node* printForward(struct Node* node)
{
    struct Node* last = NULL;
    while (node != NULL) {
        printf("%d ", node->data); last = node; node = node->next;
    }
    printf("\n");
    return last;
}

void printBackward(struct Node* last)
{
    while (last != NULL) {
        printf("%d ", last->data); last = last->prev;
    }
    printf("\n");
}

